  let score = 0, level = 1, lives = 3;
  let best = +(localStorage.getItem('bb_best') || 0);
  bestEl.textContent = best;

  const paddle = { w: 96, h: 12, x: W/2 - 48, y: H - 30, speed: 520 };
  const ball = { x: 0, y: 0, r: 7, vx: 0, vy: 0, speed: 300, stuck: true };
  let blocks = [];
  let particles = [];
  let keys = {};

  const ROW_COLORS = ['#ff5f6d','#ff9f43','#feca57','#4cd137','#48dbfb','#a29bfe'];

  function buildLevel() {
    const rows = Math.min(4 + level, 8);
    const cols = 10;
    const margin = 8, top = 50;
    const bw = (W - margin * (cols + 1)) / cols;
    const bh = 20;
    blocks = [];
    for (let r = 0; r < rows; r++) {
      for (let c = 0; c < cols; c++) {
        // 強いブロックは上位行に混ざる
        let hp = 1;
        if (level >= 2 && r < 2 && (c + r) % 3 === 0) hp = 2;
        if (level >= 4 && r === 0 && c % 2 === 0) hp = 3;
        blocks.push({
          x: margin + c * (bw + margin),
          y: top + r * (bh + margin),
          w: bw, h: bh,
          hp, maxHp: hp,
          color: ROW_COLORS[r % ROW_COLORS.length]
        });
      }
    }
  }

  function resetBall() {
    ball.stuck = true;
    ball.speed = 280 + level * 25;
    ball.vx = 0;
    ball.vy = 0;
    ball.x = paddle.x + paddle.w / 2;
    ball.y = paddle.y - ball.r - 1;
  }

  function launchBall() {
    if (!ball.stuck) return;
    ball.stuck = false;
    const ang = -Math.PI / 2 + (Math.random() * 0.6 - 0.3);
    ball.vx = Math.cos(ang) * ball.speed;
    ball.vy = Math.sin(ang) * ball.speed;
  }

  function spawnParticles(x, y, color, n = 10) {
    for (let i = 0; i < n; i++) {
      const a = Math.random() * Math.PI * 2;
      const s = 60 + Math.random() * 160;
      particles.push({ x, y, vx: Math.cos(a)*s, vy: Math.sin(a)*s, life: .5, color });
    }"}
